package com.hms.website;
import com.hms.tenancy.*; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/website/settings") public class PublicWebsiteSettingsController { private final TenantRepository tenants; private final WebsiteSettingsRepository settings; public PublicWebsiteSettingsController(TenantRepository t,WebsiteSettingsRepository s){tenants=t;settings=s;} @GetMapping public WebsiteSettings get(@PathVariable String tenantSlug){UUID id=tenants.findBySlug(tenantSlug).filter(t->t.getStatus()!=TenantStatus.SUSPENDED&&t.getStatus()!=TenantStatus.CANCELLED&&t.getStatus()!=TenantStatus.EXPIRED).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug)); return settings.findByTenantId(id).filter(WebsiteSettings::isPublished).orElseThrow(()->new IllegalArgumentException("Published website settings not found"));} }
